import{_ as a,c as t,o as r,ag as s}from"./chunks/framework.Vyheyqg9.js";const u=JSON.parse('{"title":"Express and Layered Architecture — practice","description":"","frontmatter":{},"headers":[],"relativePath":"practice/node-js/module-06-express-architecture.md","filePath":"practice/node-js/module-06-express-architecture.md"}'),i={name:"practice/node-js/module-06-express-architecture.md"};function n(o,e,l,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="express-and-layered-architecture-—-practice" tabindex="-1">Express and Layered Architecture — practice <a class="header-anchor" href="#express-and-layered-architecture-—-practice" aria-label="Permalink to “Express and Layered Architecture — practice”">​</a></h1><p><strong>Learner status: still required.</strong> These tasks were separated from the textbook; no completion is credited.</p><p><a href="./../../node-js/module-06-express-architecture.html">Textbook explanation</a> · <a href="./">Node.js practice map</a></p><h3 id="diagnostic-exercise" tabindex="-1"><span class="hub-section-number">1 </span>Diagnostic exercise <a class="header-anchor" href="#diagnostic-exercise" aria-label="Permalink to “1 Diagnostic exercise”">​</a></h3><p>Design an order endpoint that reserves stock, records an order, and requests payment.</p><p>Explain:</p><ul><li>the database transaction boundary;</li><li>why the payment call is outside that transaction;</li><li>how an outbox event is recorded;</li><li>how duplicate requests are handled;</li><li>where authorization is checked;</li><li>what happens after a crash at every step;</li><li>which failures return immediately and which become asynchronous states.</li></ul><hr><h2 id="_16-final-review-checklist" tabindex="-1"><span class="hub-section-number">2 </span>Final review checklist <a class="header-anchor" href="#_16-final-review-checklist" aria-label="Permalink to “2 Final review checklist”">​</a></h2><h3 id="use-case-reliability" tabindex="-1"><span class="hub-section-number">2.1 </span>Use-case reliability <a class="header-anchor" href="#use-case-reliability" aria-label="Permalink to “2.1 Use-case reliability”">​</a></h3><ul><li>[ ] Put a transaction around repository operations that share one invariant.</li><li>[ ] Keep slow external calls outside database transactions.</li><li>[ ] Explain the outbox pattern and idempotent consumers.</li><li>[ ] Store an idempotency result atomically with the business change.</li><li>[ ] Pass actor, tenant, deadline, and cancellation context deliberately.</li><li>[ ] Enforce critical authorization outside route middleware as well.</li><li>[ ] Analyze partial success and crash points in a multi-step workflow.</li></ul><h3 id="express-fundamentals" tabindex="-1"><span class="hub-section-number">2.2 </span>Express fundamentals <a class="header-anchor" href="#express-fundamentals" aria-label="Permalink to “2.2 Express fundamentals”">​</a></h3><ul><li>[ ] Explain what Express adds on top of <code>node:http</code>.</li><li>[ ] Create an application and keep <code>app</code> separate from <code>listen()</code>.</li><li>[ ] Read path parameters, queries, headers, and parsed request bodies.</li><li>[ ] Use appropriate response helpers and status codes.</li><li>[ ] Define resource-oriented routes and modular routers.</li></ul><h3 id="middleware-and-errors" tabindex="-1"><span class="hub-section-number">2.3 </span>Middleware and errors <a class="header-anchor" href="#middleware-and-errors" aria-label="Permalink to “2.3 Middleware and errors”">​</a></h3><ul><li>[ ] Explain why middleware order matters.</li><li>[ ] Ensure every middleware path continues, responds, or errors.</li><li>[ ] Distinguish application-, router-, and route-level middleware.</li><li>[ ] Register 404 and error handlers after routes.</li><li>[ ] Explain Express 5 and Express 4 async-error behavior.</li><li>[ ] Return a consistent safe error representation.</li></ul><h3 id="architecture" tabindex="-1"><span class="hub-section-number">2.4 </span>Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “2.4 Architecture”">​</a></h3><ul><li>[ ] Keep HTTP logic in routes/controllers.</li><li>[ ] Keep business rules and orchestration in services.</li><li>[ ] Keep persistence details in repositories.</li><li>[ ] Enforce downward dependency flow.</li><li>[ ] Use interfaces or injected dependencies where substitution helps.</li><li>[ ] Organize code by feature while preserving layer responsibilities.</li></ul><h3 id="validation-and-security" tabindex="-1"><span class="hub-section-number">2.5 </span>Validation and security <a class="header-anchor" href="#validation-and-security" aria-label="Permalink to “2.5 Validation and security”">​</a></h3><ul><li>[ ] Validate runtime input even when TypeScript types exist.</li><li>[ ] Validate body, params, query, and relevant headers.</li><li>[ ] Use parsed/validated output rather than the original input.</li><li>[ ] Reject or strip unknown fields deliberately.</li><li>[ ] Separate transport validation from business rules.</li><li>[ ] Use parameterized queries, size limits, authorization, and safe output handling.</li></ul><h2 id="correction-labs-contracts-that-the-complete-api-must-satisfy" tabindex="-1"><span class="hub-section-number">3 </span>Correction labs: contracts that the complete API must satisfy <a class="header-anchor" href="#correction-labs-contracts-that-the-complete-api-must-satisfy" aria-label="Permalink to “3 Correction labs: contracts that the complete API must satisfy”">​</a></h2><p>Baselines checked2026-10-21: Express5.3.0, Zod4.6.7 (defaults inside optional fields), Node24.18.0; the complete extracted Products API also typechecked with TypeScript5.9.3 strict/exact-optional/indexed-access checks. Keep the actual installed package versions/lockfile with results. The scratch validation environment is separate from this notes repository and does not change Autocode templates or src/tests.</p><p><strong>PATCH acceptance:</strong> creation without stock yields0; name-only PATCH output has no stock key and preserves existing stock; explicit stock0 updates correctly; empty/unknown/id/sku/undefined/null-field patches reject according to the stated schema. Normalized parsed output, not raw req.body, reaches the service. Validate returned object keys as well as values.</p><p><strong>Uniqueness acceptance:</strong> launch two service.create calls with the same normalized SKU through one real in-memory repository; require one success, one ConflictError, one stored row. Delete then recreate works. Prove that mutating a returned Product does not mutate stored primitives. Repeat the contract against the real database adapter with its unique constraint; the in-memory no-await section is not a distributed lock.</p><p><strong>Transport acceptance:</strong> malformed JSON→400, oversized entity→413, unsupported charset/encoding→415, schema error→the declared400 policy, and unexpected programmer TypeError→500. Do not expose parser body/stack in responses/logs. Assert headersSent forwards to next once. The fail-closed auth scaffold cannot pass private requests; install and test a real verifier separately. Check safe route logs with a sensitive query and unmatched route; no raw query may be recorded. Exercise startup invalid-port/error/partial-cleanup and bounded shutdown in the lifecycle lesson; this introductory server snippet does not implement all of those yet.</p><p><strong>Idempotency acceptance:</strong> the same scoped key+same normalized input replays only a completed response; different input conflicts; an atomic concurrent claim allows at most one business insertion; rollback/crash-before-commit creates neither partial business state nor a visible completed response. Record actual persistence isolation/retention behavior and replay authorization. A port/fake test cannot establish durable atomicity. Learner implementation and real DB/Express deployment evidence remain required.</p><p>Official references: <a href="https://zod.dev/v4/changelog#defaults-applied-within-optional-fields" target="_blank" rel="noreferrer">Zod4 optional defaults</a>, <a href="https://expressjs.com/en/guide/error-handling/" target="_blank" rel="noreferrer">Express5 errors</a>, <a href="https://expressjs.com/en/resources/middleware/body-parser/#errors" target="_blank" rel="noreferrer">body-parser error types</a>, <a href="https://www.postgresql.org/docs/current/sql-insert.html" target="_blank" rel="noreferrer">PostgreSQL INSERT conflict handling</a>.</p><p><strong>Acceptance drill:</strong> strict-typecheck draft/published/outcome narrowing and reject missing publication data or a draft passed to the published DTO mapper. At runtime reject invalid dates, mismatched state/date, unsafe/fractional/negative money and malformed identity. Feed a row/variable containing supplier cost, internal note, tenant and driver metadata; assert the exact public JSON keys contain none of them. Mutate the original Date after mapping and verify the domain ISO string stays unchanged.</p><p>Assert draft/wrong-tenant/absent all present as404, published as200 and no other status leaks into domain types. Add an outcome and observe a never diagnostic. Then repeat through the real repository/controller with tenant-scoped queries and a simulated database outage. The pure mapping checks do not establish server authorization, transactional storage or learner practice.</p><p><strong>Practice acceptance:</strong> build a service using the primary composition owner, inject invalid configuration, occupied-port failure, dependency acquisition failure and a later partial-startup failure. Assert owned cleanup and a nonzero outcome without leaking configuration. Test parser statuses and headersSent delegation, then reproduce the shared shutdown failure/drain/deadline cases in disposable processes. Record exactly which dependencies are real. No <code>src/tests</code> changes or remote push are permitted; independent learner practice remains required.</p>',29)])])}const m=a(i,[["render",n]]);export{u as __pageData,m as default};
